    """Duplicate the 4-shape as a reflection on the side indicated by the 6-shape."""
    h, w = len(grid), len(grid[0])
    p4 = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    p6 = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not p4 or not p6:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in p4), max(r for r, c in p4)
    c0, c1 = min(c for r, c in p4), max(c for r, c in p4)
    s0, s1 = min(r for r, c in p6), max(r for r, c in p6)
    t0, t1 = min(c for r, c in p6), max(c for r, c in p6)
    out = [row[:] for row in grid]
    for r, c in p6:
        out[r][c] = 0
    # A 6-shape symmetric top-to-bottom indicates vertical duplication below;
    # otherwise the shape indicates a left/right reflection toward the 6 object.
    p6set = set(p6)
    horizontal_sym = all((s0 + s1 - r, c) in p6set for r, c in p6)
    if horizontal_sym:
        for r, c in p4:
            rr = 2 * r1 + 1 - r
            if rr < h:
                out[rr][c] = 4
    elif (t0 + t1) <= (c0 + c1):
        for r, c in p4:
            cc = 2 * c0 - 1 - c
            if cc >= 0:
                out[r][cc] = 4
    else:
        for r, c in p4:
            cc = 2 * c1 + 1 - c
            if cc < w:
                out[r][cc] = 4
    return out
